{
  "facts": [
    {
      "topic": "scope",
      "statement": "The entry calls ZSTD_compressStream2 with flush, end, and continue directives. Compression strategy dispatch is within its operational surface.",
      "evidence": [
        {
          "unit_id": "u-9dc9e88ae722c8cbe085",
          "start_line": 59,
          "end_line": 65,
          "role": "primary",
          "dependency_reason": ""
        },
        {
